import sys

MOD = 10**9 + 7

def solve(n, s):
    stack = []
    for i in range(n):
        if s[i] == ')':
            temp = 0
            while stack[-1] != '(':
                temp += stack.pop()
                stack.pop()
            stack.pop()
            if not stack or stack[-1] == '(':
                stack.append(temp)
            else:
                stack[-1] += temp
        elif s[i] != '(':
            stack.append(int(s[i]))
        else:
            stack.append(s[i])
    return sum(stack) % MOD

def main():
    n = int(sys.stdin.readline().strip())
    s = sys.stdin.readline().strip().split()
    print(solve(n, s))

if __name__ == "__main__":
    main()

import sys

MOD = 10**9+7

def solve(n, s):
    stack = []
    for token in s:
        if token == '(':
            continue
        elif token == ')':
            num1 = stack.pop()
            operation = stack.pop()
            num2 = stack.pop()
            if operation == '+':
                res = (num1 + num2) % MOD
            else:
                res = (num1 * num2) % MOD
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0]

n = int(sys.stdin.readline().strip())
s = sys.stdin.readline().strip().split()
print(solve(n, s))

