    n = int(sys.stdin.readline().strip())
    tokens = sys.stdin.readline().strip().split()
    stack = []
    for token in tokens:
        if token == '(':
            continue
        elif token == ')':
            right = stack.pop()
            op = stack.pop()
            left = stack.pop()
            if op == '+':
                res = (left + right) % MOD
            else:
                res = (left * right) % MOD
            stack.append(res)
        else:
            stack.append(int(token))
    print(stack[0])

