MOD = 10**9 + 7

def solve(n, s):
    stack = []
    for i in range(n):
        if s[i] == ')':
            temp = 0
            while stack[-1] != '(':
                temp += stack.pop()
                stack.pop()
            stack.pop()
            if not stack or stack[-1] == '(':
                stack.append(temp % MOD)
            else:
                stack[-1] = (stack[-1] * (temp % MOD)) % MOD
        elif s[i] != '(':
            stack.append(int(s[i]))
        else:
            stack.append(s[i])
    return sum(stack) % MOD

def main():
    n = int(input().strip())
    s = input().strip().split()
    print(solve(n, s))

if __name__ == "__main__":
